class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        min_sum = float('inf')
        n = len(nums)

        # Iterate over all possible start indices
        for i in range(n):
            current_sum = 0
            # Iterate over all possible end indices
            for j in range(i, n):
                current_sum += nums[j]
                length = j - i + 1

                # If length exceeds r, we can stop checking for this start index
                if length > r:
                    break

                # Check if the current subarray length is within the range [l, r]
                if length >= l:
                    # If the sum is positive, update the minimum sum found so far
                    if current_sum > 0:
                        if current_sum < min_sum:
                            min_sum = current_sum

        # Return -1 if no valid subarray was found, otherwise return the minimum sum
        return min_sum if min_sum != float('inf') else -1

from typing import List

class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n
        for i in range(n):
            if nums[i] > 0:
                # Move nums[i] steps to the right
                # In a circular array, moving k steps right from index i lands at (i + k) % n
                target_index = (i + nums[i]) % n
                result[i] = nums[target_index]
            elif nums[i] < 0:
                # Move abs(nums[i]) steps to the left
                # In a circular array, moving k steps left from index i lands at (i - k) % n
                target_index = (i - abs(nums[i])) % n
                result[i] = nums[target_index]
            else:
                # If nums[i] == 0, result[i] is set to nums[i] (which is 0)
                result[i] = nums[i]
        return result
